/**
 * A schema-driven postcard decoder.
 *
 * `schema.json` (generated by `cargo xtask protocol` with serde-reflection) describes the serde
 * data model of every protocol type. This module walks postcard bytes along that description and
 * produces exactly the value `serde_json` would produce for the same Rust value, so the generated
 * TypeScript types apply to both transports. It is tested against Rust-encoded vectors
 * (`crates/kiln-protocol/tests/vectors`).
 *
 * Postcard rules (postcard 1.x wire format): unsigned integers above 8 bits are LEB128 varints,
 * signed ones are zigzag varints, floats are little-endian IEEE 754, strings and sequences are
 * prefixed with a varint length, options with a 0/1 byte, enums with a varint variant index;
 * structs and tuples are their fields in order.
 */

import generatedSchema from './generated/schema.json' with { type: 'json' };

/** A serde-reflection `Format` (the shape of an unnamed value). */
export type Format =
  | 'UNIT'
  | 'BOOL'
  | 'I8'
  | 'I16'
  | 'I32'
  | 'I64'
  | 'I128'
  | 'U8'
  | 'U16'
  | 'U32'
  | 'U64'
  | 'U128'
  | 'F32'
  | 'F64'
  | 'CHAR'
  | 'STR'
  | 'BYTES'
  | { TYPENAME: string }
  | { OPTION: Format }
  | { SEQ: Format }
  | { MAP: { KEY: Format; VALUE: Format } }
  | { TUPLE: Format[] }
  | { TUPLEARRAY: { CONTENT: Format; SIZE: number } };

/** A named field: `{ "<name>": Format }`. */
export type Named<T> = Record<string, T>;

/** The format of an enum variant. */
export type VariantFormat = 'UNIT' | { NEWTYPE: Format } | { TUPLE: Format[] } | { STRUCT: Named<Format>[] };

/** The format of a named container (struct or enum). */
export type ContainerFormat =
  | 'UNITSTRUCT'
  | { NEWTYPESTRUCT: Format }
  | { TUPLESTRUCT: Format[] }
  | { STRUCT: Named<Format>[] }
  | { ENUM: Record<string, Named<VariantFormat>> };

/** Every named container, by type name. */
export type Registry = Record<string, ContainerFormat>;

/** The registry of the protocol this package was generated for. */
export const SCHEMA: Registry = (generatedSchema as unknown as { types: Registry }).types;

/** Options of {@link decode}. */
export interface DecodeOptions {
  /**
   * Turn every `f32` into the shortest decimal that rounds to it (what `serde_json` prints), so
   * postcard and JSON values compare equal. Off by default: frames carry many floats and the
   * painter does not need it.
   */
  canonicalF32?: boolean;
}

/** Thrown for malformed input. */
export class PostcardError extends Error {
  override readonly name = 'PostcardError';
}

const utf8 = new TextDecoder('utf-8', { fatal: true });

/** The shortest decimal representation of a float32 value, as Rust's `{}` formatting prints it. */
export function shortestF32(x: number): number {
  if (!Number.isFinite(x) || x === 0) return x;
  for (let digits = 1; digits <= 9; digits++) {
    const candidate = Number.parseFloat(x.toPrecision(digits));
    if (Math.fround(candidate) === x) return candidate;
  }
  return x;
}

class Reader {
  private offset = 0;
  private readonly view: DataView;

  constructor(
    private readonly bytes: Uint8Array,
    private readonly registry: Registry,
    private readonly options: DecodeOptions,
  ) {
    this.view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  }

  get remaining(): number {
    return this.bytes.length - this.offset;
  }

  private need(n: number): void {
    if (this.offset + n > this.bytes.length) {
      throw new PostcardError(`unexpected end of input at byte ${this.offset} (needed ${n} more)`);
    }
  }

  private byte(): number {
    this.need(1);
    const b = this.bytes[this.offset] as number;
    this.offset += 1;
    return b;
  }

  /** An unsigned LEB128 varint of at most `bits` bits. */
  private varint(bits: number): bigint {
    const maxBytes = Math.ceil(bits / 7);
    let result = 0n;
    for (let i = 0; i < maxBytes; i++) {
      const b = this.byte();
      result |= BigInt(b & 0x7f) << BigInt(7 * i);
      if ((b & 0x80) === 0) {
        if (result >> BigInt(bits) !== 0n) throw new PostcardError(`varint overflows ${bits} bits`);
        return result;
      }
    }
    throw new PostcardError(`varint longer than ${maxBytes} bytes`);
  }

  private smallVarint(bits: number): number {
    return Number(this.varint(bits));
  }

  private zigzag(bits: number): bigint {
    const u = this.varint(bits);
    return (u & 1n) === 0n ? u >> 1n : -(u >> 1n) - 1n;
  }

  private safe(v: bigint): number {
    if (v > BigInt(Number.MAX_SAFE_INTEGER) || v < BigInt(Number.MIN_SAFE_INTEGER)) {
      throw new PostcardError(`integer ${v} does not fit a JavaScript number`);
    }
    return Number(v);
  }

  private length(): number {
    const n = this.safe(this.varint(64));
    if (n > this.remaining) {
      // Every element takes at least one byte except units; reject absurd lengths early.
      throw new PostcardError(`length ${n} exceeds the ${this.remaining} remaining bytes`);
    }
    return n;
  }

  private str(): string {
    const n = this.length();
    this.need(n);
    const slice = this.bytes.subarray(this.offset, this.offset + n);
    this.offset += n;
    try {
      return utf8.decode(slice);
    } catch {
      throw new PostcardError('invalid UTF-8 in a string');
    }
  }

  value(format: Format): unknown {
    if (typeof format === 'string') {
      switch (format) {
        case 'UNIT':
          return null;
        case 'BOOL': {
          const b = this.byte();
          if (b > 1) throw new PostcardError(`invalid bool byte ${b}`);
          return b === 1;
        }
        case 'U8':
          return this.byte();
        case 'I8': {
          const b = this.byte();
          return b > 127 ? b - 256 : b;
        }
        case 'U16':
          return this.smallVarint(16);
        case 'U32':
          return this.smallVarint(32);
        case 'U64':
          return this.safe(this.varint(64));
        case 'U128':
          return this.safe(this.varint(128));
        case 'I16':
          return Number(this.zigzag(16));
        case 'I32':
          return Number(this.zigzag(32));
        case 'I64':
          return this.safe(this.zigzag(64));
        case 'I128':
          return this.safe(this.zigzag(128));
        case 'F32': {
          this.need(4);
          const v = this.view.getFloat32(this.offset, true);
          this.offset += 4;
          return this.options.canonicalF32 ? shortestF32(v) : v;
        }
        case 'F64': {
          this.need(8);
          const v = this.view.getFloat64(this.offset, true);
          this.offset += 8;
          return v;
        }
        case 'CHAR':
        case 'STR':
          return this.str();
        case 'BYTES': {
          const n = this.length();
          this.need(n);
          const out = Array.from(this.bytes.subarray(this.offset, this.offset + n));
          this.offset += n;
          return out;
        }
      }
    }
    if ('TYPENAME' in format) return this.container(format.TYPENAME);
    if ('OPTION' in format) {
      const tag = this.byte();
      if (tag === 0) return null;
      if (tag === 1) return this.value(format.OPTION);
      throw new PostcardError(`invalid option tag ${tag}`);
    }
    if ('SEQ' in format) {
      const n = this.length();
      const out: unknown[] = new Array(n);
      for (let i = 0; i < n; i++) out[i] = this.value(format.SEQ);
      return out;
    }
    if ('MAP' in format) {
      const n = this.length();
      const out: Record<string, unknown> = {};
      for (let i = 0; i < n; i++) {
        const key = this.value(format.MAP.KEY);
        out[String(key)] = this.value(format.MAP.VALUE);
      }
      return out;
    }
    if ('TUPLE' in format) return format.TUPLE.map((f) => this.value(f));
    if ('TUPLEARRAY' in format) {
      const out: unknown[] = [];
      for (let i = 0; i < format.TUPLEARRAY.SIZE; i++) out.push(this.value(format.TUPLEARRAY.CONTENT));
      return out;
    }
    throw new PostcardError(`unknown format ${JSON.stringify(format)}`);
  }

  private fields(fields: Named<Format>[]): Record<string, unknown> {
    const out: Record<string, unknown> = {};
    for (const field of fields) {
      const [name, format] = Object.entries(field)[0] as [string, Format];
      out[name] = this.value(format);
    }
    return out;
  }

  private container(name: string): unknown {
    const c = this.registry[name];
    if (c === undefined) throw new PostcardError(`type ${name} is not in the schema`);
    if (c === 'UNITSTRUCT') return null;
    if ('NEWTYPESTRUCT' in c) return this.value(c.NEWTYPESTRUCT);
    if ('TUPLESTRUCT' in c) return c.TUPLESTRUCT.map((f) => this.value(f));
    if ('STRUCT' in c) return this.fields(c.STRUCT);
    const index = this.smallVarint(32);
    const variant = c.ENUM[String(index)];
    if (variant === undefined) throw new PostcardError(`${name} has no variant ${index}`);
    const [vname, vformat] = Object.entries(variant)[0] as [string, VariantFormat];
    if (vformat === 'UNIT') return vname;
    if ('NEWTYPE' in vformat) return { [vname]: this.value(vformat.NEWTYPE) };
    if ('TUPLE' in vformat) return { [vname]: vformat.TUPLE.map((f) => this.value(f)) };
    return { [vname]: this.fields(vformat.STRUCT) };
  }
}

/**
 * Decodes postcard `bytes` of the given format. The whole input must be consumed.
 *
 * @throws {PostcardError} on truncated, trailing or malformed input.
 */
export function decode(
  format: Format,
  bytes: Uint8Array,
  registry: Registry = SCHEMA,
  options: DecodeOptions = {},
): unknown {
  const reader = new Reader(bytes, registry, options);
  const value = reader.value(format);
  if (reader.remaining !== 0) {
    throw new PostcardError(`${reader.remaining} trailing byte(s) after the value`);
  }
  return value;
}

/** Decodes a named protocol type, e.g. `decodeAs<SceneDelta>('SceneDelta', bytes)`. */
export function decodeAs<T>(typeName: string, bytes: Uint8Array, options: DecodeOptions = {}): T {
  return decode({ TYPENAME: typeName }, bytes, SCHEMA, options) as T;
}
